import argparse,hashlib,json
p=argparse.ArgumentParser();p.add_argument('--receipt',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();base=a.receipt.resolve().parent
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def require(b,s):
    if not b:raise ValueError(s)
paths=[Path(__file__),a.receipt,base/'debugger/checkpoints.ndjson',base/'ordinary/target.ndjson',base/'debugger/target.ndjson',base/'original-Code.json'];before={str(p):sha(p)for p in paths}
